-- SnakeGame update 0001: bootstrap Solo
-- Cole todo este arquivo na Barra de Comandos do Roblox Studio em modo Edit.
-- Instala apenas objetos sob namespaces SnakeGame; recusa sobrescrever instalacao existente.
local RS=game:GetService("ReplicatedStorage")
local SSS=game:GetService("ServerScriptService")
local SPS=game:GetService("StarterPlayer"):WaitForChild("StarterPlayerScripts")
local WS=game:GetService("Workspace")
assert(not RS:FindFirstChild("SnakeGame"),"SnakeGame ja instalado: patch 0001 nao deve sobrescrever dados")
assert(not SSS:FindFirstChild("SnakeGameServer"),"SnakeGameServer ja existe")
assert(not SPS:FindFirstChild("SnakeGameClient"),"SnakeGameClient ja existe")
assert(not WS:FindFirstChild("SnakeGameArena"),"SnakeGameArena ja existe")
local serverSource="-- SnakeGame 0001 | servidor autoritativo\nlocal Players = game:GetService(\"Players\")\nlocal RS = game:GetService(\"ReplicatedStorage\")\nlocal RunService = game:GetService(\"RunService\")\nlocal root = RS:WaitForChild(\"SnakeGame\")\nlocal turn = root:WaitForChild(\"Turn\")\nlocal state = root:WaitForChild(\"State\")\nlocal arena = workspace:WaitForChild(\"SnakeGameArena\")\nlocal SIZE, CELL, STEP = 18, 4, 0.23\nlocal rng = Random.new()\nlocal sessions = {}\nlocal directions = {Up=Vector2.new(0,-1),Down=Vector2.new(0,1),Left=Vector2.new(-1,0),Right=Vector2.new(1,0)}\nlocal function key(v) return tostring(v.X)..\":\"..tostring(v.Y) end\nlocal function point(v) return Vector3.new((v.X-(SIZE-1)/2)*CELL, 3, (v.Y-(SIZE-1)/2)*CELL) end\nlocal function makePart(parent, name, size, color, material)\n    local p=Instance.new(\"Part\")\n    p.Name=name; p.Anchored=true; p.CanCollide=false; p.Size=size\n    p.Material=material or Enum.Material.SmoothPlastic\n    p.Color=color; p.Parent=parent\n    return p\nend\nlocal function send(player,s)\n    state:FireClient(player,{score=s.score,alive=s.alive,body=s.body,food=s.food,step=STEP})\nend\nlocal function spawnFood(s)\n    local occupied={}\n    for _,v in ipairs(s.body) do occupied[key(v)]=true end\n    local free={}\n    for x=0,SIZE-1 do for y=0,SIZE-1 do\n        local v=Vector2.new(x,y)\n        if not occupied[key(v)] then table.insert(free,v) end\n    end end\n    if #free==0 then return nil end\n    return free[rng:NextInteger(1,#free)]\nend\nlocal function paint(s)\n    local model=s.model\n    local segments=model:FindFirstChild(\"Segments\")\n    if not segments then segments=Instance.new(\"Folder\"); segments.Name=\"Segments\"; segments.Parent=model end\n    for i,v in ipairs(s.body) do\n        local p=segments:FindFirstChild(tostring(i))\n        if not p then p=makePart(segments,tostring(i),Vector3.new(3.35,2.5,3.35),Color3.fromRGB(61,202,105),Enum.Material.Neon) end\n        p.Color=(i==1) and Color3.fromRGB(145,255,94) or Color3.fromRGB(61,202,105)\n        p.Position=point(v)\n    end\n    for _,p in ipairs(segments:GetChildren()) do\n        if tonumber(p.Name) and tonumber(p.Name)>#s.body then p:Destroy() end\n    end\n    local food=model:FindFirstChild(\"Food\")\n    if s.food then\n        if not food then food=makePart(model,\"Food\",Vector3.new(2.8,2.8,2.8),Color3.fromRGB(255,102,109),Enum.Material.Neon); food.Shape=Enum.PartType.Ball end\n        food.Position=point(s.food)\n    elseif food then food:Destroy() end\nend\nlocal function reset(player)\n    local old=sessions[player]\n    if old and old.model then old.model:Destroy() end\n    local model=Instance.new(\"Model\"); model.Name=\"Snake_\"..player.UserId; model.Parent=arena\n    local mid=math.floor(SIZE/2)\n    local s={body={Vector2.new(mid,mid),Vector2.new(mid-1,mid),Vector2.new(mid-2,mid)},dir=directions.Right,pending=nil,score=0,alive=true,model=model,lastInput=0}\n    s.food=spawnFood(s); sessions[player]=s\n    paint(s); send(player,s)\nend\nlocal function advance(player,s)\n    if not s.alive then return end\n    if s.pending then s.dir=s.pending; s.pending=nil end\n    local head=s.body[1]+s.dir\n    local grow=s.food and head==s.food\n    local occupied={}\n    local last=#s.body-(grow and 0 or 1)\n    for i=1,last do occupied[key(s.body[i])]=true end\n    if head.X<0 or head.X>=SIZE or head.Y<0 or head.Y>=SIZE or occupied[key(head)] then\n        s.alive=false; send(player,s); return\n    end\n    table.insert(s.body,1,head)\n    if grow then s.score+=1; s.food=spawnFood(s) else table.remove(s.body) end\n    if not s.food then s.alive=false end\n    paint(s); send(player,s)\nend\nturn.OnServerEvent:Connect(function(player,command)\n    if typeof(command)~=\"string\" then return end\n    local s=sessions[player]\n    if not s then return end\n    local now=os.clock()\n    if now-s.lastInput<0.045 then return end\n    s.lastInput=now\n    if command==\"Restart\" then if not s.alive then reset(player) end; return end\n    local dir=directions[command]\n    if not dir or not s.alive then return end\n    local reference=s.pending or s.dir\n    if dir~=reference and dir~=-s.dir then s.pending=dir end\nend)\nPlayers.PlayerAdded:Connect(reset)\nPlayers.PlayerRemoving:Connect(function(p)\n    local s=sessions[p]; if s and s.model then s.model:Destroy() end; sessions[p]=nil\nend)\nfor _,p in ipairs(Players:GetPlayers()) do reset(p) end\nlocal accumulator=0\nRunService.Heartbeat:Connect(function(dt)\n    accumulator+=math.min(dt,0.25)\n    local n=0\n    while accumulator>=STEP and n<3 do\n        accumulator-=STEP; n+=1\n        for player,s in pairs(sessions) do advance(player,s) end\n    end\nend)\n"
local clientSource="-- SnakeGame 0001 | interface e controles\nlocal Players=game:GetService(\"Players\")\nlocal RS=game:GetService(\"ReplicatedStorage\")\nlocal UIS=game:GetService(\"UserInputService\")\nlocal player=Players.LocalPlayer\nlocal root=RS:WaitForChild(\"SnakeGame\")\nlocal turn=root:WaitForChild(\"Turn\")\nlocal state=root:WaitForChild(\"State\")\nlocal gui=Instance.new(\"ScreenGui\")\ngui.Name=\"SnakeGameHUD\"; gui.ResetOnSpawn=false; gui.IgnoreGuiInset=true; gui.Parent=player:WaitForChild(\"PlayerGui\")\nlocal function label(name,text,pos,size)\n    local t=Instance.new(\"TextLabel\")\n    t.Name=name; t.BackgroundTransparency=1; t.Text=text\n    t.TextColor3=Color3.fromRGB(235,255,250); t.Font=Enum.Font.GothamBold\n    t.TextScaled=true; t.Position=pos; t.Size=size; t.Parent=gui\n    local c=Instance.new(\"UITextSizeConstraint\"); c.MaxTextSize=34; c.MinTextSize=12; c.Parent=t\n    return t\nend\nlocal score=label(\"Score\",\"PONTOS  0\",UDim2.fromScale(.36,.03),UDim2.fromScale(.28,.07))\nlocal hint=label(\"Hint\",\"WASD / SETAS  •  TOQUE PARA VIRAR\",UDim2.fromScale(.22,.91),UDim2.fromScale(.56,.05))\nlocal retry=Instance.new(\"TextButton\")\nretry.Name=\"Retry\"; retry.Text=\"RECOMEÇAR\"; retry.Font=Enum.Font.GothamBold\nretry.TextScaled=true; retry.BackgroundColor3=Color3.fromRGB(28,195,161)\nretry.TextColor3=Color3.fromRGB(12,31,31); retry.Size=UDim2.fromScale(.26,.075)\nretry.Position=UDim2.fromScale(.37,.46); retry.Visible=false; retry.Parent=gui\nInstance.new(\"UICorner\",retry).CornerRadius=UDim.new(0,12)\nretry.Activated:Connect(function() turn:FireServer(\"Restart\") end)\nlocal buttons={}\nfor _,info in ipairs({{\"Up\",\"↑\",.87,.69},{\"Left\",\"←\",.79,.78},{\"Down\",\"↓\",.87,.78},{\"Right\",\"→\",.95,.78}}) do\n    local b=Instance.new(\"TextButton\")\n    b.Name=info[1]; b.Text=info[2]; b.Font=Enum.Font.GothamBold\n    b.TextScaled=true; b.BackgroundColor3=Color3.fromRGB(26,73,70)\n    b.TextColor3=Color3.fromRGB(210,255,232)\n    b.AnchorPoint=Vector2.new(.5,.5); b.Position=UDim2.fromScale(info[3],info[4])\n    b.Size=UDim2.fromScale(.075,.085); b.Parent=gui\n    Instance.new(\"UICorner\",b).CornerRadius=UDim.new(.22,0)\n    b.Activated:Connect(function() turn:FireServer(info[1]) end)\n    table.insert(buttons,b)\nend\nlocal keys={\n    [Enum.KeyCode.W]=\"Up\",[Enum.KeyCode.Up]=\"Up\",\n    [Enum.KeyCode.S]=\"Down\",[Enum.KeyCode.Down]=\"Down\",\n    [Enum.KeyCode.A]=\"Left\",[Enum.KeyCode.Left]=\"Left\",\n    [Enum.KeyCode.D]=\"Right\",[Enum.KeyCode.Right]=\"Right\"\n}\nUIS.InputBegan:Connect(function(input,processed)\n    if processed then return end\n    local direction=keys[input.KeyCode]\n    if direction then turn:FireServer(direction) end\nend)\nstate.OnClientEvent:Connect(function(s)\n    if typeof(s)~=\"table\" then return end\n    score.Text=\"PONTOS  \"..tostring(s.score or 0)\n    retry.Visible=s.alive==false\n    hint.Text=(s.alive==false) and \"FIM DE JOGO\" or \"WASD / SETAS  •  TOQUE PARA VIRAR\"\nend)\nlocal camera=workspace.CurrentCamera\nlocal function setCamera()\n    camera=workspace.CurrentCamera\n    if camera then\n        camera.CameraType=Enum.CameraType.Scriptable\n        camera.CFrame=CFrame.lookAt(Vector3.new(0,90,65),Vector3.new(0,0,0))\n        camera.FieldOfView=55\n    end\nend\nsetCamera()\nworkspace:GetPropertyChangedSignal(\"CurrentCamera\"):Connect(setCamera)\n"
local created={}
local function add(class,name,parent)
    local x=Instance.new(class); x.Name=name; x.Parent=parent
    table.insert(created,x); return x
end
local ok,err=pcall(function()
    local net=add("Folder","SnakeGame",RS)
    add("RemoteEvent","Turn",net)
    add("RemoteEvent","State",net)
    local arena=add("Model","SnakeGameArena",WS)
    local floor=add("Part","Floor",arena)
    floor.Anchored=true; floor.Size=Vector3.new(72,1,72)
    floor.Position=Vector3.new(0,-.5,0)
    floor.Material=Enum.Material.SmoothPlastic
    floor.Color=Color3.fromRGB(20,38,39)
    for i=-9,9 do
        for axis=1,2 do
            local p=add("Part","Grid",arena)
            p.Anchored=true; p.CanCollide=false
            p.Material=Enum.Material.Neon
            p.Color=Color3.fromRGB(36,63,63)
            p.Transparency=.45
            p.Size=(axis==1) and Vector3.new(.07,.04,72) or Vector3.new(72,.04,.07)
            p.Position=(axis==1) and Vector3.new(i*4,.04,0) or Vector3.new(0,.04,i*4)
        end
    end
    local server=add("Script","SnakeGameServer",SSS)
    server.Enabled=false; server.Source=serverSource
    local client=add("LocalScript","SnakeGameClient",SPS)
    client.Enabled=false; client.Source=clientSource
    assert(#server.Source>100 and #client.Source>100,"Falha ao instalar fontes")
    assert(net:FindFirstChild("Turn") and net:FindFirstChild("State"),"Remotes ausentes")
    server.Enabled=true; client.Enabled=true
end)
if not ok then
    for i=#created,1,-1 do if created[i].Parent then created[i]:Destroy() end end
    error("SnakeGame 0001 rollback: "..tostring(err))
end
print("[SnakeGame] 0001 instalado: Solo, arena, HUD e controles. Execute Play para testar.")
